import{_ as a,o as e,c as s,ag as n}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Network Conditioning","description":"Simulate real-world network conditions to test your application under constrained environments.","frontmatter":{"title":"Network Conditioning","description":"Simulate real-world network conditions to test your application under constrained environments."},"headers":[],"relativePath":"features/network-conditioning.md","filePath":"features/network-conditioning.md","lastUpdated":1772297611000}'),o={name:"features/network-conditioning.md"};function i(l,t,r,d,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="network-conditioning" tabindex="-1">Network Conditioning <a class="header-anchor" href="#network-conditioning" aria-label="Permalink to &quot;Network Conditioning&quot;">​</a></h1><p>Network Conditioning lets you simulate real-world network environments by throttling bandwidth, adding latency, introducing jitter, and simulating packet loss. This is essential for testing how your application performs for users on slow mobile networks, high-latency satellite connections, or unreliable Wi-Fi.</p><h2 id="why-network-conditioning-matters" tabindex="-1">Why Network Conditioning Matters <a class="header-anchor" href="#why-network-conditioning-matters" aria-label="Permalink to &quot;Why Network Conditioning Matters&quot;">​</a></h2><p>Most developers build and test applications on fast, low-latency connections. But real users access applications from a wide range of network conditions:</p><ul><li>A user on a 2G network in a rural area</li><li>A commuter on a crowded train with degraded 3G connectivity</li><li>A user behind a corporate DSL connection</li><li>A user with spotty hotel Wi-Fi</li></ul><p>Network conditioning lets you experience your application the way these users do, so you can identify and fix performance issues, optimize loading states, and build a better experience for everyone.</p><h2 id="built-in-profiles" tabindex="-1">Built-In Profiles <a class="header-anchor" href="#built-in-profiles" aria-label="Permalink to &quot;Built-In Profiles&quot;">​</a></h2><p>NectoProxy includes <strong>11 pre-configured network profiles</strong> that simulate common real-world conditions. Select a profile from the network conditioning dropdown in the toolbar to activate it immediately.</p><h3 id="mobile-network-profiles" tabindex="-1">Mobile Network Profiles <a class="header-anchor" href="#mobile-network-profiles" aria-label="Permalink to &quot;Mobile Network Profiles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Download</th><th>Upload</th><th>Latency</th><th>Typical Scenario</th></tr></thead><tbody><tr><td><strong>Slow 2G</strong></td><td>280 Kbps</td><td>256 Kbps</td><td>1400 ms</td><td>GPRS in rural or low-signal areas</td></tr><tr><td><strong>Regular 2G</strong></td><td>450 Kbps</td><td>150 Kbps</td><td>800 ms</td><td>Standard EDGE connectivity</td></tr><tr><td><strong>Good 2G</strong></td><td>900 Kbps</td><td>280 Kbps</td><td>650 ms</td><td>Strong EDGE signal</td></tr><tr><td><strong>Slow 3G</strong></td><td>780 Kbps</td><td>330 Kbps</td><td>400 ms</td><td>Degraded UMTS connectivity</td></tr><tr><td><strong>Regular 3G</strong></td><td>1.5 Mbps</td><td>750 Kbps</td><td>300 ms</td><td>Standard HSPA connection</td></tr><tr><td><strong>Good 3G</strong></td><td>4 Mbps</td><td>1.5 Mbps</td><td>170 ms</td><td>Strong HSPA+ signal</td></tr><tr><td><strong>Regular 4G</strong></td><td>9 Mbps</td><td>4 Mbps</td><td>50 ms</td><td>Standard LTE connection</td></tr></tbody></table><h3 id="fixed-network-profiles" tabindex="-1">Fixed Network Profiles <a class="header-anchor" href="#fixed-network-profiles" aria-label="Permalink to &quot;Fixed Network Profiles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Download</th><th>Upload</th><th>Latency</th><th>Typical Scenario</th></tr></thead><tbody><tr><td><strong>DSL</strong></td><td>2 Mbps</td><td>1 Mbps</td><td>50 ms</td><td>Standard DSL broadband</td></tr><tr><td><strong>WiFi</strong></td><td>30 Mbps</td><td>15 Mbps</td><td>10 ms</td><td>Typical home or office Wi-Fi</td></tr></tbody></table><h3 id="special-profiles" tabindex="-1">Special Profiles <a class="header-anchor" href="#special-profiles" aria-label="Permalink to &quot;Special Profiles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Profile</th><th>Effect</th><th>Description</th></tr></thead><tbody><tr><td><strong>Offline</strong></td><td>100% packet loss</td><td>Simulates complete network disconnection. All requests fail.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Offline Mode</p><p>The Offline profile drops all traffic. Your application will experience network errors on every request. This is useful for testing offline-capable applications, service worker caching behavior, and error states.</p></div><h2 id="profile-details" tabindex="-1">Profile Details <a class="header-anchor" href="#profile-details" aria-label="Permalink to &quot;Profile Details&quot;">​</a></h2><h3 id="slow-2g" tabindex="-1">Slow 2G <a class="header-anchor" href="#slow-2g" aria-label="Permalink to &quot;Slow 2G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  280 Kbps</span></span>
<span class="line"><span>Upload:    256 Kbps</span></span>
<span class="line"><span>Latency:   1400 ms</span></span></code></pre></div><p>Simulates the slowest cellular connection still in use. At 280 Kbps download speed with 1.4 seconds of latency, even a small 50 KB API response takes several seconds to load. Use this profile to test:</p><ul><li>Critical loading path optimization</li><li>Progressive enhancement strategies</li><li>Timeout configurations</li><li>Skeleton screen and placeholder implementations</li></ul><h3 id="regular-2g" tabindex="-1">Regular 2G <a class="header-anchor" href="#regular-2g" aria-label="Permalink to &quot;Regular 2G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  450 Kbps</span></span>
<span class="line"><span>Upload:    150 Kbps</span></span>
<span class="line"><span>Latency:   800 ms</span></span></code></pre></div><p>A standard 2G EDGE connection. Still very slow by modern standards, but noticeably faster than Slow 2G. Good for testing how your application performs when basic connectivity is available but constrained.</p><h3 id="good-2g" tabindex="-1">Good 2G <a class="header-anchor" href="#good-2g" aria-label="Permalink to &quot;Good 2G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  900 Kbps</span></span>
<span class="line"><span>Upload:    280 Kbps</span></span>
<span class="line"><span>Latency:   650 ms</span></span></code></pre></div><p>The best-case 2G experience. Download speeds approach 1 Mbps, but latency remains high. Image-heavy pages and large JavaScript bundles will still load slowly.</p><h3 id="slow-3g" tabindex="-1">Slow 3G <a class="header-anchor" href="#slow-3g" aria-label="Permalink to &quot;Slow 3G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  780 Kbps</span></span>
<span class="line"><span>Upload:    330 Kbps</span></span>
<span class="line"><span>Latency:   400 ms</span></span></code></pre></div><p>Degraded 3G connectivity, common in areas with weak signal or network congestion. Download speeds are comparable to Good 2G, but latency is significantly lower.</p><h3 id="regular-3g" tabindex="-1">Regular 3G <a class="header-anchor" href="#regular-3g" aria-label="Permalink to &quot;Regular 3G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  1.5 Mbps</span></span>
<span class="line"><span>Upload:    750 Kbps</span></span>
<span class="line"><span>Latency:   300 ms</span></span></code></pre></div><p>A standard 3G HSPA connection. This is the experience for a large number of mobile users worldwide. At 1.5 Mbps, most web pages load within 5-10 seconds. A good baseline for mobile performance testing.</p><h3 id="good-3g" tabindex="-1">Good 3G <a class="header-anchor" href="#good-3g" aria-label="Permalink to &quot;Good 3G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  4 Mbps</span></span>
<span class="line"><span>Upload:    1.5 Mbps</span></span>
<span class="line"><span>Latency:   170 ms</span></span></code></pre></div><p>A strong HSPA+ connection. At 4 Mbps download, most content loads at an acceptable speed, but the 170 ms latency still adds noticeable delay to interactive operations.</p><h3 id="regular-4g" tabindex="-1">Regular 4G <a class="header-anchor" href="#regular-4g" aria-label="Permalink to &quot;Regular 4G&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  9 Mbps</span></span>
<span class="line"><span>Upload:    4 Mbps</span></span>
<span class="line"><span>Latency:   50 ms</span></span></code></pre></div><p>Standard LTE connectivity. This is perceived as a &quot;good&quot; connection by most users. At 9 Mbps with 50 ms latency, most applications perform well, but large downloads and real-time features may still feel slightly impacted compared to broadband.</p><h3 id="dsl" tabindex="-1">DSL <a class="header-anchor" href="#dsl" aria-label="Permalink to &quot;DSL&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  2 Mbps</span></span>
<span class="line"><span>Upload:    1 Mbps</span></span>
<span class="line"><span>Latency:   50 ms</span></span></code></pre></div><p>A typical DSL broadband connection. The asymmetric speeds (2 Mbps down, 1 Mbps up) with low latency represent a common home broadband experience in many regions. Good for testing file upload scenarios.</p><h3 id="wifi" tabindex="-1">WiFi <a class="header-anchor" href="#wifi" aria-label="Permalink to &quot;WiFi&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:  30 Mbps</span></span>
<span class="line"><span>Upload:    15 Mbps</span></span>
<span class="line"><span>Latency:   10 ms</span></span></code></pre></div><p>A typical home or office Wi-Fi connection. This is close to an unconstrained experience for most web applications. Useful as a &quot;mild constraint&quot; profile to verify that your application works well on a good but not perfect connection.</p><h3 id="offline" tabindex="-1">Offline <a class="header-anchor" href="#offline" aria-label="Permalink to &quot;Offline&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Packet Loss:  100%</span></span></code></pre></div><p>All network traffic is dropped. No requests reach the server, and no responses are delivered to the client. Use this to test:</p><ul><li>Offline-first application behavior</li><li>Service worker cache fallbacks</li><li>Local storage persistence</li><li>&quot;No connection&quot; UI states</li><li>Retry mechanisms when connectivity is restored</li></ul><h2 id="custom-profiles" tabindex="-1">Custom Profiles <a class="header-anchor" href="#custom-profiles" aria-label="Permalink to &quot;Custom Profiles&quot;">​</a></h2><p>If the built-in profiles do not match your testing needs, you can create <strong>custom network profiles</strong> with precise control over every parameter.</p><h3 id="configurable-parameters" tabindex="-1">Configurable Parameters <a class="header-anchor" href="#configurable-parameters" aria-label="Permalink to &quot;Configurable Parameters&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Unit</th><th>Description</th><th>Range</th></tr></thead><tbody><tr><td><strong>Download Bandwidth</strong></td><td>Kbps or Mbps</td><td>Maximum download throughput</td><td>0 -- unlimited</td></tr><tr><td><strong>Upload Bandwidth</strong></td><td>Kbps or Mbps</td><td>Maximum upload throughput</td><td>0 -- unlimited</td></tr><tr><td><strong>Latency</strong></td><td>Milliseconds</td><td>Additional delay added to each request</td><td>0 -- 30000 ms</td></tr><tr><td><strong>Jitter</strong></td><td>Milliseconds</td><td>Random variation in latency (plus or minus)</td><td>0 -- 5000 ms</td></tr><tr><td><strong>Packet Loss</strong></td><td>Percentage</td><td>Probability that a request is dropped</td><td>0% -- 100%</td></tr></tbody></table><h3 id="creating-a-custom-profile" tabindex="-1">Creating a Custom Profile <a class="header-anchor" href="#creating-a-custom-profile" aria-label="Permalink to &quot;Creating a Custom Profile&quot;">​</a></h3><ol><li>Open the <strong>Network Conditioning</strong> panel in the toolbar</li><li>Click <strong>Custom Profile</strong></li><li>Set each parameter to your desired value</li><li>Optionally save the profile with a name for reuse</li></ol><details class="details custom-block"><summary>Example: Simulating Unstable Hotel Wi-Fi</summary><p>Hotel Wi-Fi is notoriously unreliable. Create a custom profile to simulate it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:     5 Mbps</span></span>
<span class="line"><span>Upload:       2 Mbps</span></span>
<span class="line"><span>Latency:      80 ms</span></span>
<span class="line"><span>Jitter:       150 ms</span></span>
<span class="line"><span>Packet Loss:  5%</span></span></code></pre></div><p>The jitter introduces random latency variation (80 ms +/- 150 ms, so anywhere from 0 to 230 ms), and the 5% packet loss simulates the occasional dropped connection that characterizes unreliable networks.</p></details><details class="details custom-block"><summary>Example: Simulating Satellite Internet</summary><p>Satellite connections have high bandwidth but extreme latency:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Download:     25 Mbps</span></span>
<span class="line"><span>Upload:       3 Mbps</span></span>
<span class="line"><span>Latency:      600 ms</span></span>
<span class="line"><span>Jitter:       50 ms</span></span>
<span class="line"><span>Packet Loss:  1%</span></span></code></pre></div><p>This profile tests how your application handles a scenario where individual requests are fast to transfer but the round-trip time is very high.</p></details><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="performance-budgeting" tabindex="-1">Performance Budgeting <a class="header-anchor" href="#performance-budgeting" aria-label="Permalink to &quot;Performance Budgeting&quot;">​</a></h3><p>Set a target network profile (e.g., Regular 3G) and measure whether your application loads within your performance budget. If your page takes 15 seconds to become interactive on 3G, you have identified an optimization opportunity.</p><h3 id="loading-state-validation" tabindex="-1">Loading State Validation <a class="header-anchor" href="#loading-state-validation" aria-label="Permalink to &quot;Loading State Validation&quot;">​</a></h3><p>Slow networks reveal loading states that are invisible on fast connections. Enable a Slow 2G or Regular 3G profile and verify that your application displays appropriate loading indicators, skeleton screens, and progress bars while content loads.</p><h3 id="timeout-and-retry-testing" tabindex="-1">Timeout and Retry Testing <a class="header-anchor" href="#timeout-and-retry-testing" aria-label="Permalink to &quot;Timeout and Retry Testing&quot;">​</a></h3><p>Verify that your application&#39;s timeout configurations and retry logic work correctly under high-latency conditions. A request that completes in 200 ms on a local network might take 3 seconds on a Slow 3G connection -- does your timeout handle this gracefully?</p><h3 id="image-and-asset-optimization" tabindex="-1">Image and Asset Optimization <a class="header-anchor" href="#image-and-asset-optimization" aria-label="Permalink to &quot;Image and Asset Optimization&quot;">​</a></h3><p>Enable a constrained profile and observe how images, fonts, and JavaScript bundles load. This often reveals opportunities for lazy loading, responsive images, code splitting, and other optimization techniques.</p><h3 id="error-state-testing" tabindex="-1">Error State Testing <a class="header-anchor" href="#error-state-testing" aria-label="Permalink to &quot;Error State Testing&quot;">​</a></h3><p>Use the Offline profile or a high packet-loss custom profile to test your application&#39;s error handling. Verify that failed requests produce meaningful error messages and that users can recover gracefully.</p><hr><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Network conditioning applies to <strong>all traffic</strong> flowing through NectoProxy. To condition only specific requests, combine network conditioning with <a href="./rules-engine.html">Rules Engine</a> delay and throttle actions for targeted control.</p></div>`,69)])])}const g=a(o,[["render",i]]);export{u as __pageData,g as default};
